// KM2-W4 parity: the phone's own verdict on 1,620 words (app/Tests/KenningWordParity/phone-verdicts.json, regenerated by
// app/scripts/kenning-word-parity-check.sh) against the server's keywordProblem, so server and phone cannot drift again. $0.
// Two directions: a word the phone refuses must never leave the server as a station word (else the phone draws a fallback or the dot),
// and a word the phone draws must not be refused by the server (else good words are lost).
import { assert, assertEquals } from "jsr:@std/assert@1";
import { cleanKeyword, keywordProblem } from "../engine/keyword.ts";

const verdicts: Record<string, boolean> = JSON.parse(
  Deno.readTextFileSync(new URL("./fixtures/phone_verdicts.json", import.meta.url)),
);

Deno.test("word parity fixture: the phone's verdicts are all there (1,620 words, 13 drawn)", () => {
  const words = Object.keys(verdicts);
  assert(words.length >= 1600, `only ${words.length} words`);
  assert(words.filter((w) => verdicts[w]).length >= 13);
  for (const w of ["Therapies", "Pregnancies", "Diagnoses", "Peace"]) assertEquals(verdicts[w], false, w);
  for (const w of ["Plans", "Walks", "Dinner", "Laughter", "Credit", "Sunday", "Timing", "Evenings", "Afterthought", "Help"]) {
    assertEquals(verdicts[w], true, w);
  }
});

Deno.test("word parity: every word the phone refuses, the server refuses", () => {
  const leaks = Object.keys(verdicts).filter((w) => !verdicts[w] && keywordProblem(w) === null);
  assertEquals(leaks, [], `server accepts words the phone refuses: ${leaks.join(", ")}`);
  assertEquals(Object.keys(verdicts).filter((w) => !verdicts[w] && cleanKeyword(w) !== null), []);
});

Deno.test("word parity: every word the phone draws, the server keeps", () => {
  const lost = Object.keys(verdicts).filter((w) => verdicts[w] && keywordProblem(w) !== null);
  assertEquals(lost, [], `server refuses words the phone draws: ${lost.join(", ")}`);
});
